#include <limits.h>

#define MAXN 300
#define MAXAB 50

int d[MAXAB+1][MAXAB+1];
int A, B;

int main() {
    scanf("%d %d", &A, &B);
    for (int x = 1; x <= A; x++) {
        for (int y = 1; y <= B; y++) {
            scanf("%d", &d[x][y]);
        }
    }

    // We'll try to find a set of (a,b,fixed) such that
    // d[x][y] = min_{k} (fixed_k + a_k*x + b_k*y)
    // We can guess that planes come from (a,b) pairs where
    // a = d[x+1][y] - d[x][y], b = d[x][y+1] - d[x][y] for some x,y
    // and fixed = d[1][1] - a*1 - b*1

    int used_a[100] = {0}, used_b[100] = {0}, used_fixed[100];
    int cnt = 0;

    for (int x = 1; x < A; x++) {
        for (int y = 1; y < B; y++) {
            int a = d[x+1][y] - d[x][y];
            int b = d[x][y+1] - d[x][y];
            int fixed = d[x][y] - a*x - b*y;
            // check if this plane is valid for all points
            int ok = 1;
            for (int xx = 1; xx <= A && ok; xx++) {
                for (int yy = 1; yy <= B && ok; yy++) {
                    if (fixed + a*xx + b*yy < d[xx][yy]) ok = 0;
                }
            }
            if (ok) {
                // check duplicate
                int dup = 0;
                for (int i = 0; i < cnt; i++) {
                    if (used_a[i] == a && used_b[i] == b && used_fixed[i] == fixed) {
                        dup = 1; break;
                    }
                }
                if (!dup) {
                    used_a[cnt] = a;
                    used_b[cnt] = b;
                    used_fixed[cnt] = fixed;
                    cnt++;
                }
            }
        }
    }

    // Also add plane from (1,1) itself
    int a0 = 0, b0 = 0, fixed0 = d[1][1];
    int ok0 = 1;
    for (int xx = 1; xx <= A && ok0; xx++)
        for (int yy = 1; yy <= B && ok0; yy++)
            if (fixed0 < d[xx][yy]) ok0 = 0;
    if (ok0) {
        int dup = 0;
        for (int i = 0; i < cnt; i++)
            if (used_a[i]==a0 && used_b[i]==b0 && used_fixed[i]==fixed0) dup=1;
        if (!dup) {
            used_a[cnt]=a0; used_b[cnt]=b0; used_fixed[cnt]=fixed0; cnt++;
        }
    }

    // Verify that with these planes we match all d[x][y]
    for (int x = 1; x <= A; x++) {
        for (int y = 1; y <= B; y++) {
            int minv = INT_MAX;
            for (int i = 0; i < cnt; i++) {
                int val = used_fixed[i] + used_a[i]*x + used_b[i]*y;
                if (val < minv) minv = val;
            }
            if (minv != d[x][y]) {
                printf("Impossible\n");
                return 0;
            }
        }
    }

    // Build the graph
    // Vertices: 1 = S, 2 = T, then for each plane we add a chain
    int V = 2;
    // We'll store edges: from, to, weight (or -1 for X, -2 for Y)
    int from[10000], to[10000], w[10000];
    int edgecnt = 0;

    for (int i = 0; i < cnt; i++) {
        int a = used_a[i], b = used_b[i], fixed = used_fixed[i];
        int prev = 1; // S
        // a times X
        for (int j = 0; j < a; j++) {
            V++;
            from[edgecnt] = prev;
            to[edgecnt] = V;
            w[edgecnt] = -1; // X
            edgecnt++;
            prev = V;
        }
        // b times Y
        for (int j = 0; j < b; j++) {
            V++;
            from[edgecnt] = prev;
            to[edgecnt] = V;
            w[edgecnt] = -2; // Y
            edgecnt++;
            prev = V;
        }
        // fixed weight edge to T
        from[edgecnt] = prev;
        to[edgecnt] = 2;
        w[edgecnt] = fixed;
        edgecnt++;
    }

    // Output
    printf("%d %d\n", V, edgecnt);
    for (int i = 0; i < edgecnt; i++) {
        if (w[i] == -1) printf("%d %d X\n", from[i], to[i]);
        else if (w[i] == -2) printf("%d %d Y\n", from[i], to[i]);
        else printf("%d %d %d\n", from[i], to[i], w[i]);
    }

    return 0;
}

