    // If impossible:
    // Impossible

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int u, v;
        String w;
        Edge(int u, int v, String w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int A, B;
        try {
            A = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        B = fs.nextInt();

        int[][] d = new int[A + 1][B + 1];
        for (int x = 1; x <= A; x++) {
            for (int y = 1; y <= B; y++) {
                d[x][y] = fs.nextInt();
            }
        }

        // Try to fit:
        // d(x,y) = min(c00, c10 + x, c01 + y, c11 + x + y)
        // Since x,y start from 1, derive candidates from minima.
        int INF = 1 << 29;

        int c00 = INF, c10 = INF, c01 = INF, c11 = INF;
        for (int x = 1; x <= A; x++) {
            for (int y = 1; y <= B; y++) {
                c00 = Math.min(c00, d[x][y]);
                c10 = Math.min(c10, d[x][y] - x);
                c01 = Math.min(c01, d[x][y] - y);
                c11 = Math.min(c11, d[x][y] - x - y);
            }
        }

        // Need constants in [0,100].
        int[] c = {c00, c10, c01, c11};
        for (int v : c) {
            if (v < 0 || v > 100) {
                System.out.println("Impossible");
                return;
            }
        }

        boolean ok = true;
        for (int x = 1; x <= A && ok; x++) {
            for (int y = 1; y <= B; y++) {
                int val = Math.min(
                        Math.min(c00, c10 + x),
                        Math.min(c01 + y, c11 + x + y)
                );
                if (val != d[x][y]) {
                    ok = false;
                    break;
                }
            }
        }

        if (!ok) {
            System.out.println("Impossible");
            return;
        }

        List<Edge> edges = new ArrayList<>();
        int S = 1;
        int T = 2;
        int next = 3;

        // path for c00: S -> T with weight c00
        edges.add(new Edge(S, T, String.valueOf(c00)));

        // path for c10: S -X-> v ->T(c10)
        {
            int v = next++;
            edges.add(new Edge(S, v, "X"));
            edges.add(new Edge(v, T, String.valueOf(c10)));
        }

        // path for c01: S -Y-> v ->T(c01)
        {
            int v = next++;
            edges.add(new Edge(S, v, "Y"));
            edges.add(new Edge(v, T, String.valueOf(c01)));
        }

        // path for c11: S -X-> v1 -Y-> v2 ->T(c11)
        {
            int v1 = next++;
            int v2 = next++;
            edges.add(new Edge(S, v1, "X"));
            edges.add(new Edge(v1, v2, "Y"));
            edges.add(new Edge(v2, T, String.valueOf(c11)));
        }

        int N = next - 1;
        int M = edges.size();

        StringBuilder sb = new StringBuilder();
        sb.append(N).append(' ').append(M).append(' ').append(S).append(' ').append(T).append('\n');
        for (Edge e : edges) {
            sb.append(e.u).append(' ').append(e.v).append(' ').append(e.w).append('\n');
        }
        System.out.print(sb.toString());
    }
